changeSet.sql:
LOCK TABLE practice_area, practice IN SHARE MODE;

DELETE FROM practice_catalog_installation installation
WHERE NOT EXISTS (
    SELECT 1
    FROM practice_area area
    WHERE area.workspace_id = installation.workspace_id
)
  AND NOT EXISTS (
    SELECT 1
    FROM practice
    WHERE practice.workspace_id = installation.workspace_id
);

ALTER TABLE config_audit_event ALTER COLUMN workspace_id DROP NOT NULL;
ALTER TABLE config_audit_event DROP CONSTRAINT ck_config_audit_event_entity_type;
ALTER TABLE config_audit_event ADD CONSTRAINT ck_config_audit_event_entity_type
    CHECK (entity_type IN (
        'PRACTICE_REVIEW_SETTINGS', 'AGENT_BINDING', 'AGENT_CONFIG', 'AI_CONFIG_BINDING',
        'WORKSPACE_ROLE', 'WORKSPACE_FEATURES', 'WORKSPACE_STATUS',
        'WORKSPACE_TOKEN', 'WORKSPACE_VISIBILITY', 'PRACTICE_ACTIVE',
        'PRACTICE_DEFINITION', 'PRACTICE_AREA', 'CURATED_PRACTICE', 'CURATED_PRACTICE_AREA',
        'WORKSPACE_INSTANCE_LLM_BUDGET', 'WORKSPACE_OWN_PROVIDER_LLM_BUDGET',
        'WORKSPACE_LLM_BUDGET', 'WORKSPACE_BYO_LLM_BUDGET',
        'WORKSPACE_LLM_CONNECTION', 'WORKSPACE_LLM_MODEL'
    ));
ALTER TABLE config_audit_event ADD CONSTRAINT ck_config_audit_event_scope
    CHECK (
        (entity_type IN ('CURATED_PRACTICE', 'CURATED_PRACTICE_AREA') AND workspace_id IS NULL)
        OR (entity_type NOT IN ('CURATED_PRACTICE', 'CURATED_PRACTICE_AREA')
            AND workspace_id IS NOT NULL)
    );

rollback.sql:
DO $rollback$
BEGIN
    ALTER TABLE config_audit_event DROP CONSTRAINT IF EXISTS ck_config_audit_event_scope;
    IF EXISTS (SELECT 1 FROM config_audit_event WHERE workspace_id IS NULL) THEN
        RAISE WARNING 'config_audit_event.workspace_id remains nullable because instance-scoped audit rows exist';
    ELSE
        ALTER TABLE config_audit_event ALTER COLUMN workspace_id SET NOT NULL;
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM config_audit_event
        WHERE entity_type IN ('PRACTICE_AREA', 'CURATED_PRACTICE', 'CURATED_PRACTICE_AREA')
    ) THEN
        ALTER TABLE config_audit_event DROP CONSTRAINT ck_config_audit_event_entity_type;
        ALTER TABLE config_audit_event ADD CONSTRAINT ck_config_audit_event_entity_type
            CHECK (entity_type IN (
                'PRACTICE_REVIEW_SETTINGS', 'AGENT_BINDING', 'AGENT_CONFIG', 'AI_CONFIG_BINDING',
                'WORKSPACE_ROLE', 'WORKSPACE_FEATURES', 'WORKSPACE_STATUS',
                'WORKSPACE_TOKEN', 'WORKSPACE_VISIBILITY', 'PRACTICE_ACTIVE',
                'PRACTICE_DEFINITION',
                'WORKSPACE_INSTANCE_LLM_BUDGET', 'WORKSPACE_OWN_PROVIDER_LLM_BUDGET',
                'WORKSPACE_LLM_BUDGET', 'WORKSPACE_BYO_LLM_BUDGET',
                'WORKSPACE_LLM_CONNECTION', 'WORKSPACE_LLM_MODEL'
            ));
    END IF;
END
$rollback$;

changeSet.sql:
ALTER TABLE practice_revision ADD COLUMN slug VARCHAR(64), ADD COLUMN name VARCHAR(128), ADD COLUMN applies_to VARCHAR(32), ADD COLUMN trigger_events JSONB, ADD COLUMN precompute_script TEXT, ADD COLUMN why_it_matters TEXT, ADD COLUMN what_good_looks_like TEXT, ADD COLUMN area_slug VARCHAR(64), ADD COLUMN area_name VARCHAR(128), ADD COLUMN area_description TEXT, ADD COLUMN area_icon VARCHAR(64), ADD COLUMN area_color VARCHAR(32), ADD COLUMN detection_fingerprint VARCHAR(64);
ALTER TABLE practice ADD COLUMN current_revision_id BIGINT, ADD COLUMN source_curated_slug VARCHAR(64), ADD COLUMN source_curated_fingerprint VARCHAR(64);
INSERT INTO practice_revision ( practice_id, revision_number, criteria, created_at, slug, name, applies_to, trigger_events, precompute_script, why_it_matters, what_good_looks_like, area_slug, area_name, area_description, area_icon, area_color ) SELECT practice.id, COALESCE(max_revision.revision_number, 0) + 1, practice.criteria, CURRENT_TIMESTAMP, practice.slug, practice.name, practice.applies_to, practice.trigger_events, practice.precompute_script, practice.why_it_matters, practice.what_good_looks_like, area.slug, area.name, area.description, area.icon, area.color FROM practice LEFT JOIN practice_area area ON area.id = practice.practice_area_id LEFT JOIN ( SELECT practice_id, max(revision_number) AS revision_number FROM practice_revision GROUP BY practice_id ) max_revision ON max_revision.practice_id = practice.id;
UPDATE practice SET current_revision_id = current_revision.id FROM practice_revision current_revision WHERE current_revision.practice_id = practice.id AND current_revision.revision_number = ( SELECT max(candidate.revision_number) FROM practice_revision candidate WHERE candidate.practice_id = practice.id );
ALTER TABLE practice_revision ADD CONSTRAINT ck_practice_revision_number CHECK (revision_number >= 1), ADD CONSTRAINT ck_practice_revision_definition_shape CHECK ( ( slug IS NULL AND name IS NULL AND applies_to IS NULL AND trigger_events IS NULL AND detection_fingerprint IS NULL ) OR ( slug IS NOT NULL AND name IS NOT NULL AND applies_to IS NOT NULL AND trigger_events IS NOT NULL ) ), ADD CONSTRAINT ck_practice_revision_applies_to CHECK (applies_to IS NULL OR applies_to IN ('PULL_REQUEST', 'ISSUE', 'CONVERSATION_THREAD')), ADD CONSTRAINT ck_practice_revision_trigger_events CHECK (trigger_events IS NULL OR jsonb_typeof(trigger_events) = 'array'), ADD CONSTRAINT ck_practice_revision_fingerprint CHECK (detection_fingerprint IS NULL OR detection_fingerprint ~ '^[0-9a-f]{64}$');
ALTER TABLE practice ADD CONSTRAINT uk_practice_current_revision UNIQUE (current_revision_id), ADD CONSTRAINT fk_practice_current_revision FOREIGN KEY (current_revision_id) REFERENCES practice_revision(id), ADD CONSTRAINT ck_practice_curated_origin CHECK ((source_curated_slug IS NULL) = (source_curated_fingerprint IS NULL)), ADD CONSTRAINT ck_practice_curated_fingerprint CHECK (source_curated_fingerprint IS NULL OR source_curated_fingerprint ~ '^[0-9a-f]{64}$');
CREATE INDEX idx_practice_source_curated_slug ON practice(source_curated_slug) WHERE source_curated_slug IS NOT NULL;
CREATE FUNCTION enforce_practice_revision_immutability() RETURNS trigger LANGUAGE plpgsql AS $immutable_revision$ BEGIN -- Allow one-time fingerprint backfill; all other revision fields remain immutable. IF NEW.practice_id = OLD.practice_id AND NEW.revision_number = OLD.revision_number AND NEW.created_at = OLD.created_at AND NEW.slug IS NOT DISTINCT FROM OLD.slug AND NEW.name IS NOT DISTINCT FROM OLD.name AND NEW.applies_to IS NOT DISTINCT FROM OLD.applies_to AND NEW.trigger_events IS NOT DISTINCT FROM OLD.trigger_events AND NEW.criteria = OLD.criteria AND NEW.precompute_script IS NOT DISTINCT FROM OLD.precompute_script AND NEW.why_it_matters IS NOT DISTINCT FROM OLD.why_it_matters AND NEW.what_good_looks_like IS NOT DISTINCT FROM OLD.what_good_looks_like AND NEW.area_slug IS NOT DISTINCT FROM OLD.area_slug AND NEW.area_name IS NOT DISTINCT FROM OLD.area_name AND NEW.area_description IS NOT DISTINCT FROM OLD.area_description AND NEW.area_icon IS NOT DISTINCT FROM OLD.area_icon AND NEW.area_color IS NOT DISTINCT FROM OLD.area_color AND ( NEW.detection_fingerprint IS NOT DISTINCT FROM OLD.detection_fingerprint OR OLD.detection_fingerprint IS NULL ) THEN RETURN NEW; END IF; RAISE EXCEPTION 'practice revisions are immutable' USING ERRCODE = '55000'; END; $immutable_revision$;
CREATE TRIGGER practice_revision_immutable_update BEFORE UPDATE ON practice_revision FOR EACH ROW EXECUTE FUNCTION enforce_practice_revision_immutability();
CREATE FUNCTION enforce_practice_current_revision_projection() RETURNS trigger LANGUAGE plpgsql AS $current_projection$ BEGIN IF NOT EXISTS ( SELECT 1 FROM practice practice JOIN practice_revision revision ON revision.id = practice.current_revision_id AND revision.practice_id = practice.id LEFT JOIN practice_area area ON area.id = practice.practice_area_id WHERE practice.id = NEW.id AND revision.slug = practice.slug AND revision.name = practice.name AND revision.applies_to = practice.applies_to AND revision.trigger_events = practice.trigger_events AND revision.criteria = practice.criteria AND revision.precompute_script IS NOT DISTINCT FROM practice.precompute_script AND revision.why_it_matters IS NOT DISTINCT FROM practice.why_it_matters AND revision.what_good_looks_like IS NOT DISTINCT FROM practice.what_good_looks_like AND revision.area_slug IS NOT DISTINCT FROM area.slug ) THEN RAISE EXCEPTION 'practice current revision does not match its current projection' USING ERRCODE = '23514'; END IF; RETURN NULL; END; $current_projection$;
CREATE CONSTRAINT TRIGGER practice_requires_current_revision_projection AFTER INSERT OR UPDATE OF current_revision_id, slug, name, applies_to, trigger_events, criteria, precompute_script, why_it_matters, what_good_looks_like, practice_area_id ON practice DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION enforce_practice_current_revision_projection();

rollback.sql:
DROP TRIGGER IF EXISTS practice_requires_current_revision_projection ON practice; DROP FUNCTION IF EXISTS enforce_practice_current_revision_projection(); DROP TRIGGER IF EXISTS practice_revision_immutable_update ON practice_revision; DROP FUNCTION IF EXISTS enforce_practice_revision_immutability();
ALTER TABLE practice DROP CONSTRAINT IF EXISTS fk_practice_current_revision, DROP CONSTRAINT IF EXISTS uk_practice_current_revision, DROP CONSTRAINT IF EXISTS ck_practice_curated_origin, DROP CONSTRAINT IF EXISTS ck_practice_curated_fingerprint; UPDATE practice SET current_revision_id = NULL;
-- Rolling back drops the columns that hold a definition, so the rows that exist only -- to carry one go with them. Identified structurally rather than by a derived column: -- a revision written before this changeset has no definition and is left alone. DELETE FROM practice_revision WHERE slug IS NOT NULL;
DROP INDEX IF EXISTS idx_practice_source_curated_slug;
ALTER TABLE practice_revision DROP CONSTRAINT IF EXISTS ck_practice_revision_number, DROP CONSTRAINT IF EXISTS ck_practice_revision_definition_shape, DROP CONSTRAINT IF EXISTS ck_practice_revision_applies_to, DROP CONSTRAINT IF EXISTS ck_practice_revision_trigger_events, DROP CONSTRAINT IF EXISTS ck_practice_revision_fingerprint;
ALTER TABLE practice DROP COLUMN IF EXISTS current_revision_id, DROP COLUMN IF EXISTS source_curated_slug, DROP COLUMN IF EXISTS source_curated_fingerprint; ALTER TABLE practice_revision DROP COLUMN IF EXISTS detection_fingerprint, DROP COLUMN IF EXISTS area_color, DROP COLUMN IF EXISTS area_icon, DROP COLUMN IF EXISTS area_description, DROP COLUMN IF EXISTS area_name, DROP COLUMN IF EXISTS area_slug, DROP COLUMN IF EXISTS what_good_looks_like, DROP COLUMN IF EXISTS why_it_matters, DROP COLUMN IF EXISTS precompute_script, DROP COLUMN IF EXISTS trigger_events, DROP COLUMN IF EXISTS applies_to, DROP COLUMN IF EXISTS name, DROP COLUMN IF EXISTS slug;

changeSet.sql:
ALTER TABLE practice_area ADD COLUMN source_curated_slug VARCHAR(64), ADD COLUMN source_curated_fingerprint VARCHAR(64), ADD CONSTRAINT ck_practice_area_curated_origin CHECK ((source_curated_slug IS NULL) = (source_curated_fingerprint IS NULL)), ADD CONSTRAINT ck_practice_area_curated_fingerprint CHECK (source_curated_fingerprint IS NULL OR source_curated_fingerprint ~ '^[0-9a-f]{64}$');
CREATE INDEX idx_practice_area_source_curated_slug ON practice_area(source_curated_slug) WHERE source_curated_slug IS NOT NULL;
ALTER TABLE practice_catalog_installation ADD COLUMN provenance_linked_at TIMESTAMP(6) WITH TIME ZONE;
-- The released marker changeset inserted one row for every workspace, whether or not it -- installed the catalog. Close those ambiguous bulk markers, except for the legacy -- lowest-id workspace. Markers written later by the runtime seeder remain eligible for -- immutable-definition matching. UPDATE practice_catalog_installation SET provenance_linked_at = installed_at WHERE workspace_id <> (SELECT MIN(id) FROM workspace) AND installed_at <= ( SELECT MAX(dateexecuted) FROM databasechangelog WHERE id = '1785274902740-4' AND author = 'hephaestus' );

rollback.sql:
DROP INDEX IF EXISTS idx_practice_area_source_curated_slug;
ALTER TABLE practice_area
    DROP CONSTRAINT IF EXISTS ck_practice_area_curated_origin,
    DROP CONSTRAINT IF EXISTS ck_practice_area_curated_fingerprint,
    DROP COLUMN IF EXISTS source_curated_slug,
    DROP COLUMN IF EXISTS source_curated_fingerprint;
ALTER TABLE practice_catalog_installation DROP COLUMN IF EXISTS provenance_linked_at;
